#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import base64, py_compile, shutil, subprocess, sys
from datetime import datetime
from pathlib import Path
PATCH_ID="9.0.12i3a"
TARGET_NAME="smoke_test_equipment_class_compatibility.py"
TOOL_SOURCE=base64.b64decode("").decode("utf-8")
def fail(msg):
 print("❌ "+msg); raise SystemExit(1)
def main():
 here=Path(__file__).resolve(); root=None
 for r in (here.parent.parent,Path.cwd(),Path.cwd().parent):
  r=r.resolve()
  if (r/"db.py").is_file() and (r/"tools").is_dir(): root=r; break
 if root is None: fail("Не знайдено корінь ROM.")
 target=root/"tools"/TARGET_NAME; backup=None
 if target.exists() and target.read_text(encoding="utf-8-sig")!=TOOL_SOURCE:
  bd=root/"backup"; bd.mkdir(exist_ok=True)
  backup=bd/f"tools_{TARGET_NAME}_{PATCH_ID}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.bak"
  shutil.copy2(target,backup)
 target.write_text(TOOL_SOURCE,encoding="utf-8")
 try:
  py_compile.compile(str(target),doraise=True)
  result=subprocess.run([sys.executable,str(target)],cwd=root)
  if result.returncode: raise RuntimeError(f"audit exit code {result.returncode}")
 except Exception as exc:
  if backup: shutil.copy2(backup,target)
  elif target.exists(): target.unlink()
  fail(f"Аудит не пройдено; інсталяцію відкочено: {exc}")
 print(f"✅ Патч {PATCH_ID} успішно застосовано.")
 print(f"✅ Створено: tools\\{TARGET_NAME}")
 print("✅ Створено звіт: DB_CLEANUP_9_0_12I3A_CLASS_COMPATIBILITY_AUDIT.md")
 print("✅ Legacy captures та gameplay-код не змінено.")
 print("Резервні копії:")
 print("   "+(str(backup.relative_to(root)) if backup else "не потрібні — новий файл"))
 print("Перевірка повторно:")
 print(f"   python .\\tools\\{TARGET_NAME}")
if __name__=="__main__": main()
